export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

// One booking rule set per category. "standard" caps guests at 2, so its
// extraGuestFee never fires; "suite" bills extra above 2 guests; "villa" adds
// a flat cleaning fee and enforces a minimum stay with its own message.
interface CategoryRules {
  minNights: number;
  maxNights: number;
  maxGuests: number;
  minStayError?: string;
  perNight: number;
  highSurcharge: number;
  flatFee: number;
  extraGuestFee: number;
}

const CATEGORIES: Record<string, CategoryRules> = {
  standard: { minNights: 1, maxNights: 14, maxGuests: 2, perNight: 80, highSurcharge: 30, flatFee: 0, extraGuestFee: 0 },
  suite:    { minNights: 1, maxNights: 21, maxGuests: 4, perNight: 150, highSurcharge: 60, flatFee: 0, extraGuestFee: 25 },
  villa:    { minNights: 3, maxNights: 28, maxGuests: 8, perNight: 300, highSurcharge: 120, flatFee: 500, extraGuestFee: 0, minStayError: "villa minimum stay" },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category;
  const rules = typeof category === "string" ? CATEGORIES[category] : undefined;
  if (rules === undefined) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > rules.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < rules.minNights) {
    return { ok: false, error: rules.minStayError ?? "bad nights" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > rules.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  // VIP card and 3+ loyalty years grant the same perks in every category:
  // a 10% discount and the flexible cancellation policy.
  const privileged = req.coupon === "VIP" || (req.loyaltyYears as number) >= 3;

  let total = rules.perNight * nights;
  if (req.season === "high") {
    total += rules.highSurcharge * nights;
  }
  if (privileged) {
    total -= Math.floor(total / 10);
  }
  if (guests > 2) {
    total += rules.extraGuestFee;
  }
  total += rules.flatFee;

  const policy = privileged ? "flex" : "strict";
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

